inline nlohmann::json ExtensionStat::ToJson() const
{
	auto json = nlohmann::json::object();

	json["type"] = type;
	if (!payload.is_null())
	{
		json["payload"] = payload;
	}

	return json;
}

inline ExtensionStat ExtensionStat::FromJson(const nlohmann::json& json)
{
	ExtensionStat result;

	if (!json.is_object())
	{
		return result;
	}

	if (auto value = detail::Read<std::string>(json, "type"))
	{
		result.type = std::move(*value);
	}
	if (auto it = json.find("payload"); it != json.end() && !it->is_null())
	{
		result.payload = *it;
	}

	return result;
}

inline nlohmann::json ClientMetaData::ToJson() const
{
	auto json = nlohmann::json::object();

	json["type"] = type;
	if (!payload.is_null())
	{
		json["payload"] = payload;
	}
	if (peerConnectionId.has_value())
	{
		json["peerConnectionId"] = (*peerConnectionId);
	}
	if (trackId.has_value())
	{
		json["trackId"] = (*trackId);
	}
	if (ssrc.has_value())
	{
		json["ssrc"] = (*ssrc);
	}
	if (timestamp.has_value())
	{
		json["timestamp"] = detail::WholeOrFraction((*timestamp));
	}

	return json;
}

inline ClientMetaData ClientMetaData::FromJson(const nlohmann::json& json)
{
	ClientMetaData result;

	if (!json.is_object())
	{
		return result;
	}

	if (auto value = detail::Read<std::string>(json, "type"))
	{
		result.type = std::move(*value);
	}
	if (auto it = json.find("payload"); it != json.end() && !it->is_null())
	{
		result.payload = *it;
	}
	result.peerConnectionId = detail::Read<std::string>(json, "peerConnectionId");
	result.trackId = detail::Read<std::string>(json, "trackId");
	result.ssrc = detail::Read<int64_t>(json, "ssrc");
	result.timestamp = detail::Read<double>(json, "timestamp");

	return result;
}

